def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

primes = []
current = 2
while len(primes) < 10:
    if is_prime(current):
        primes.append(current)
    current += 1

for p in primes:
    print(p)
